-- Checklist for Seoul Garden – Glen Waverly, from the client's "Scope of
-- Work V1.1 (12/08/2026)", pages 1–2, on the 28-day cycle (needs migration
-- 0055_checklist_28_day_cycle.sql). Run once in the Supabase SQL editor. It
-- then appears in the Admin Dashboard under Checklists → Create Checklist,
-- where it can be edited, and is assigned under Assign Checklist.
--
-- Main tasks: Windows, Dine-In Area, Entrance, Self-Serving Area,
-- Back of House (Kitchen), All Washrooms.
-- Subtasks: Item/Surface + Task, e.g. "Glass Doors – Spot Clean", each with
-- the document's frequency:
--   Daily / As Required → daily (all 28 days)        28 subtasks
--   Weekly              → weekly, on the day shaded blue  12 subtasks
--   Monthly             → monthly, Week 1 on the day shaded yellow  10 subtasks
--   (Washroom doors "2 Days" is shaded only on Wednesday, so it's weekly on Wednesday.)
-- Week 1 starts Monday 9 Nov 2026 and the cycle repeats every 28 days
-- (night shift 11:00 pm – 8:00 am, 7 days).
--
-- The company "Seoul Garden" and its site "Glen Waverly" must already exist
-- (Companies page in the dashboard), since a site needs its real location.

do $$
declare
  v_company uuid;
  v_site uuid;
begin
  select id into v_company from public.companies where name ilike 'Seoul Garden%' order by created_at limit 1;
  if v_company is null then
    raise exception 'Add the company "Seoul Garden" in the dashboard (Companies) first, then run this again.';
  end if;

  select id into v_site from public.sites
   where company_id = v_company and name ilike 'Glen Wav%'
   order by created_at limit 1;
  if v_site is null then
    raise exception 'Add the site "Glen Waverly" under Seoul Garden in the dashboard (Companies) first, then run this again.';
  end if;

  insert into public.checklist_templates (company_id, site_id, areas, day_areas, visit_dates, special_note, cycle_start, cycle_repeats, cycle_areas)
